    state: { id: 'state', name: 'Relaxation vs active state', channels: ['C3', 'O1'], classes: ['Relaxed', 'Active'], cmd: ['REST', 'GO'],
      desc: 'Relaxed rest shows strong alpha; active thinking shows stronger beta and weaker alpha. Differences are set by the simulator profiles.',
      bands(cls, ch, strength) { const a = cls === 0 ? [4, 6, 10 + 8 * strength, 4, 0.9] : [3.5, 4.5, 10 - 4 * strength, 7 + 7 * strength, 2.5]; return a; } },
    visual: { id: 'visual', name: 'Visual stimulus response', channels: ['O1', 'O2'], classes: ['Eyes open', 'Eyes closed'], cmd: ['OFF', 'ON'],
      desc: 'Closing the eyes is known to boost the occipital alpha rhythm (the Berger effect). Here: eyes closed → alpha is stronger at O1/O2.',
      bands(cls, ch, strength) { return [4, 5, cls === 1 ? 10 + 9 * strength : 10 - 5 * strength, 6, 1.2]; } },
    command: { id: 'command', name: 'Three-way command', channels: ['C3', 'C4'], classes: ['Left', 'Right', 'Stop'], cmd: ['LEFT', 'RIGHT', 'STOP'],
      desc: 'Left and right imagery as above, plus an idle “stop” class with no lateralised change. Used to drive the cursor and command panel.',
      bands(cls, ch, strength) { if (cls === 2) return BASE.slice(); const contra = cls === 0 ? 'C4' : 'C3'; return ch === contra ? BASE.map((v, i) => v * erd(1 - strength)[i]) : BASE.slice(); } },
